// The grid is deliberately small and deliberately fixed. Every cell is one
// Bright Data request per run forever, and - more importantly - the diff below
// only means something if the same cells are swept every morning. A grid that
// varies run to run turns "nobody is bidding on this any more" into "we did not
// look this time".
//
// single-item input: Settings emits one row and the grid is built once per sweep.
const cfg = $('Settings').first().json;

function list(v) {
  return String(v == null ? '' : v)
    .split('|')
    .map(function (s) { return s.trim(); })
    .filter(function (s, i, a) { return a.indexOf(s) === i; });
}

const brand = String(cfg.brand_name || '').trim();
if (!brand) {
  throw new Error('Set brand_name in Settings to the brand you want watched, for example acme');
}

// An empty modifier is the bare brand query, which is the one that matters most,
// so the empty string is kept rather than filtered out.
const mods = list(cfg.query_modifiers);
if (!mods.length) mods.push('');

// A market is `country=City,Region,Country`. Both halves matter and they do
// different jobs: `gl` picks which Google, the city picks which auction.
//
// Measured 2026-08-28, four brand queries run twice inside a minute: with `gl`
// alone they returned two ads between them, with a city attached they returned
// twelve. Google's ad auction is geographic, and a request that names no place
// barely runs one - so a country-only sweep of a brand reports a quiet morning
// almost every morning, which is the most expensive way for this to be wrong.
const markets = list(cfg.markets).filter(Boolean).map(function (m) {
  const at = m.indexOf('=');
  const cc = (at < 0 ? m : m.slice(0, at)).trim().toLowerCase();
  const place = at < 0 ? '' : m.slice(at + 1).trim();
  // Google's gl wants a lowercase ISO-2 code. A country *name* puts a space in
  // the URL, and Bright Data answers that with a validation error carrying HTTP
  // 200 - which the HTTP node's neverError then swallows, so the failure would
  // surface two nodes later blaming the parser.
  if (!/^[a-z]{2}$/.test(cc)) {
    throw new Error('Each market starts with a lowercase ISO-2 country code, as in us=Dallas,Texas,United States. Not valid: ' + m);
  }
  return { country: cc, location: place };
});
if (!markets.length) markets.push({ country: 'us', location: '' });

// The Code node sandbox has no `URL` and no `URLSearchParams`, but it does have
// `Buffer` - which is the only reason the uule below can be built here rather
// than in a second workflow.
function b64(s) {
  try { return Buffer.from(s, 'utf8').toString('base64'); }
  catch (e) { return btoa(unescape(encodeURIComponent(s))); }
}

// Google encodes "pretend the searcher is standing here" as a uule: a fixed
// prefix, one character standing for the length of the place name, then the
// place name in base64. Verified live - a request carrying this came back with
// `general.location: "Dallas, Texas"` and a local pack for that city.
function uule(place) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  return 'w+CAIQICI' + alphabet.charAt(place.length % alphabet.length) + b64(place);
}

const cap = Math.max(1, Number(cfg.max_queries) || 24);
const rows = [];
for (let ci = 0; ci < markets.length; ci++) {
  for (let mi = 0; mi < mods.length; mi++) {
    const mod = mods[mi];
    const market = markets[ci];
    const query = mod ? brand + ' ' + mod : brand;
    let url = 'https://www.google.com/search?q=' + encodeURIComponent(query)
      + '&gl=' + encodeURIComponent(market.country)
      + '&hl=en&brd_json=1';
    if (market.location) url += '&uule=' + encodeURIComponent(uule(market.location));
    rows.push({
      query: query,
      modifier: mod || '(brand alone)',
      country: market.country,
      location: market.location || market.country.toUpperCase(),
      serp_url: url,
    });
  }
}

if (rows.length > cap) {
  // Trimmed from the end rather than sampled, for the same reason the grid is
  // fixed: a random subset makes yesterday's absence unreadable.
  rows.length = cap;
}

const sweptAt = new Date().toISOString();
return rows.map(function (r) {
  return { json: Object.assign({ swept_at: sweptAt }, r) };
});

// The SERP zone is called with `format: json`, and that returns the whole HTTP
// envelope - { status_code, headers, body } - with the parsed SERP nested in
// `body` as a STRING. Reading `top_ads` off the top level finds nothing and
// reports a clean sweep, which is the wrong direction to fail in.
function unwrapSerp(x) {
  let p = x;
  if (p && p.body != null) p = p.body;
  if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch (e) { p = {}; }
  } else if (p && typeof p.data === 'string') {
    try { p = JSON.parse(p.data); } catch (e) { p = {}; }
  } else if (p && p.data && typeof p.data === 'object') {
    p = p.data;
  }
  return p || {};
}

function host(u) {
  let s = String(u == null ? '' : u).trim();
  // A display URL is a breadcrumb, not a link: `https://www.engagebay.com >
  // switch > savecosts`. Everything after the first separator is path.
  s = s.split(/[\s›>]/)[0];
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '');
  s = s.replace(/[\/?#].*$/, '');
  return s.toLowerCase();
}

function isGoogle(h) {
  return /(^|\.)google\.[a-z.]+$/.test(h || '');
}

// Measured 2026-08-28 on `car insurance quotes`: three of four ads carried
// `link: https://www.google.com/aclk?...`, a click tracker, while display_link
// read `https://www.nerdwallet.com > insurance > car`. Reading `link` first
// credits those ads to Google. The visible URL is the honest field; the real
// destination only has to be dug out when even that is a redirect.
function advertiser(ad) {
  let h = host(ad.display_link);
  if (h && !isGoogle(h)) return h;
  h = host(ad.link);
  if (h && !isGoogle(h)) return h;
  const raw = String(ad.referral_link || ad.link || '');
  const m = raw.match(/[?&]adurl=([^&]+)/) || raw.match(/[?&]q=(https?[^&]+)/);
  if (m) {
    let dug = '';
    try { dug = host(decodeURIComponent(m[1])); } catch (e) { dug = host(m[1]); }
    if (dug && !isGoogle(dug)) return dug;
  }
  // Everything resolved to Google, which means the click tracker won. Measured
  // 2026-08-28: one ad on `hubspot alternative` came through this way and was
  // filed against `google.com`, which reads as Google advertising against
  // HubSpot. An unattributable ad is dropped and counted rather than credited
  // to the tracker that hid it.
  return '';
}

const out = [];
let seen = 0;
let unresolved = 0;
const items = $input.all();
const grid = $('Build The Query Grid').all();

for (let i = 0; i < items.length; i++) {
  const cell = grid[i];
  const meta = cell ? cell.json : {};
  const body = unwrapSerp(items[i].json);

  // Bright Data answers a validation error or a rate limit with HTTP 200 and an
  // error body, and both retryOnFail and neverError swallow that silently.
  if (body.error) {
    throw new Error('Bright Data SERP returned an error for "' + (meta.query || '?') + '": ' + JSON.stringify(body.error).slice(0, 300));
  }

  // Both blocks, every time. `hubspot alternative` filled top_ads and left
  // bottom_ads empty; `asana alternative` did the opposite.
  const blocks = [['top', body.top_ads || []], ['bottom', body.bottom_ads || []]];
  const seenHere = {};

  for (let b = 0; b < blocks.length; b++) {
    const slot = blocks[b][0];
    const ads = blocks[b][1];
    for (let a = 0; a < ads.length; a++) {
      const ad = ads[a] || {};
      seen += 1;
      const who = advertiser(ad);
      if (!who) { unresolved += 1; continue; }
      // One advertiser can hold both a top and a bottom slot on the same query.
      // That is one bidder, not two.
      const key = who + '|' + meta.query + '|' + meta.country + '|' + meta.location;
      if (seenHere[key]) continue;
      seenHere[key] = true;

      const sitelinks = (ad.extensions || []).filter(function (e) {
        return e && e.type === 'site_link';
      }).length;

      out.push({ json: {
        advertiser: who,
        query: String(meta.query || ''),
        modifier: String(meta.modifier || ''),
        country: String(meta.country || ''),
        location: String(meta.location || ''),
        slot: slot,
        rank: Number(ad.rank || ad.global_rank || 0) || 0,
        headline: String(ad.title || '').replace(/\s+/g, ' ').trim(),
        ad_copy: String(ad.description || '').replace(/\s+/g, ' ').trim(),
        sitelinks: sitelinks,
        landing: String(ad.display_link || ad.link || '').split(/[\s›>]/)[0],
        swept_at: String(meta.swept_at || ''),
      }});
    }
  }
}

// A morning with no ads anywhere is a real and common outcome, and a node that
// returns zero items ends its branch - which would take the roster maths, the
// sheet and the "who stopped bidding" reading down with it. One marker item
// keeps the branch alive and carries no advertiser, so nothing counts it.
// One unattributable ad is an oddity. Every ad unattributable is the parser
// having stopped working, and the difference matters: the first is worth
// nothing, the second would otherwise report a clean sweep forever.
if (seen > 0 && unresolved === seen) {
  throw new Error('All ' + seen + ' ads this sweep resolved to a Google click tracker with no destination. The ad record shape has probably changed - check display_link and adurl in one response before trusting another run.');
}

if (!out.length) {
  return [{ json: { advertiser: '', query: '', country: '', location: '', no_ads: true } }];
}
return out;

// Everything the report says about time is decided here, and all of it comes
// out of one measurement: the same query returned zero ads on one call and four
// on the next, minutes apart. Google runs an auction per request, so a single
// response is a sample of who is bidding, never the list.
//
// Two consequences, and they are why this node exists rather than a simple
// "is it in the table" check:
//   * presence is a count of sweeps, not a fact about this morning;
//   * absence is only believed after `gone_after` sweeps in a row miss it.
const cfg = $('Settings').first().json;
const goneAfter = Math.max(1, Number(cfg.gone_after) || 3);
const now = new Date().toISOString();
const today = now.slice(0, 10);

function list(v) {
  return String(v == null ? '' : v)
    .split('|')
    .map(function (s) {
      return s.trim().toLowerCase()
        .replace(/^https?:\/\//, '')
        .replace(/^www\./, '')
        .replace(/[\/?#].*$/, '');
    })
    .filter(Boolean);
}
const mine = list(cfg.your_domains);
const partners = list(cfg.authorised_partners);

function owned(d) {
  return mine.some(function (m) { return d === m || d.endsWith('.' + m); });
}
function authorised(d) {
  return partners.some(function (p) { return d === p || d.endsWith('.' + p); });
}
function relationOf(d) {
  if (owned(d)) return 'you';
  if (authorised(d)) return 'authorised';
  return 'rival';
}

// Measured 2026-08-28 across four consecutive sweeps: Google returned the same
// creative as `Switch to Lightfield | A CRM as Ambitious as You Are` on one
// sweep and `Switch to Lightfield - A CRM as Ambitious as You Are` on the next.
// The advertiser changed nothing; Google picked a different separator for the
// layout it drew. Comparing the raw strings therefore reports a rewrite every
// few days on ads nobody has touched, which is exactly the kind of false
// positive that gets a channel muted. The raw headline is still what gets
// stored and shown - only the comparison is normalised.
function headlineKey(h) {
  return String(h == null ? '' : h)
    .toLowerCase()
    .replace(/[|–—‒-]+/g, ' ')
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/\s+/g, ' ')
    .trim();
}

// The roster is keyed per advertiser *per cell*, and a cell is a query in a
// place. A rival bidding your brand in London and not in Dallas is two
// different facts, and collapsing them into one row would hide whichever one
// changed - which matters more here than anywhere, because the ad auction is
// geographic in the first place.
const roster = {};
$('Read The Roster').all().forEach(function (i) {
  const r = i.json || {};
  if (r.watch_key) roster[String(r.watch_key)] = r;
});

// Which cells actually ran this morning. A cell that was trimmed out of the grid
// must not age its advertisers towards "stopped bidding" - that would report a
// departure caused by a settings change.
const sweptCells = {};
$('Build The Query Grid').all().forEach(function (i) {
  sweptCells[String(i.json.query) + '|' + String(i.json.country) + '|' + String(i.json.location)] = true;
});

const rows = [];
const seenNow = {};

// The sightings are read back by name, not off $input. This node sits directly
// below `Read The Roster`, so its input is the *table* - reading $input here
// walks the history and never sees a single ad, on a run where every node is
// green and the report says nothing happened.
$('Read Both Ad Blocks').all().forEach(function (i) {
  const s = i.json || {};
  if (!s.advertiser) return;
  const key = s.advertiser + '|' + s.query + '|' + s.country + '|' + s.location;
  seenNow[key] = true;

  const prior = roster[key];
  const sweeps = (prior ? Number(prior.sweeps_seen) || 0 : 0) + 1;
  const priorHeadline = prior ? String(prior.last_headline || '') : '';

  rows.push(Object.assign({}, s, {
    watch_key: key,
    relation: relationOf(s.advertiser),
    status: 'live',
    is_new: !prior,
    rewritten: !!prior && !!priorHeadline && headlineKey(priorHeadline) !== headlineKey(s.headline),
    sweeps_seen: sweeps,
    misses: 0,
    first_seen: prior && prior.first_seen ? String(prior.first_seen) : today,
    last_seen: today,
    prior_headline: priorHeadline,
    checked_at: now,
  }));
});

// Everyone the table knows who did not turn up in a cell that genuinely ran.
Object.keys(roster).forEach(function (key) {
  if (seenNow[key]) return;
  const r = roster[key];
  const cell = String(r.query || '') + '|' + String(r.country || '') + '|' + String(r.location || '');
  if (!sweptCells[cell]) return;

  const misses = (Number(r.misses) || 0) + 1;
  const who = String(r.advertiser || '');
  rows.push({
    watch_key: key,
    advertiser: who,
    query: String(r.query || ''),
    modifier: '',
    country: String(r.country || ''),
    location: String(r.location || ''),
    slot: '',
    rank: 0,
    headline: String(r.last_headline || ''),
    ad_copy: '',
    sitelinks: 0,
    landing: '',
    relation: relationOf(who),
    // The whole point of the sampling measurement. One miss is noise.
    status: misses >= goneAfter ? 'stopped' : 'missing',
    just_stopped: misses === goneAfter,
    is_new: false,
    rewritten: false,
    sweeps_seen: Number(r.sweeps_seen) || 0,
    misses: misses,
    first_seen: String(r.first_seen || today),
    last_seen: String(r.last_seen || ''),
    prior_headline: String(r.last_headline || ''),
    checked_at: now,
  });
});

if (!rows.length) {
  return [{ json: { watch_key: '', advertiser: '', status: 'nothing', checked_at: now } }];
}
return rows.map(function (r) { return { json: r }; });

// The model is the only per-item cost in the run, so it reads what changed and
// nothing else. On a settled morning that is zero ads out of forty, and the
// sweep costs one Bright Data request per cell and not a token more.
const rows = $input.all().map(function (i) { return i.json; });

const worth = rows.filter(function (r) {
  if (!r.advertiser) return false;
  // Your own ads and your resellers' are logged, never read. They are the ads
  // you are paying for.
  if (r.relation !== 'rival') return false;
  if (r.status === 'live') return !!r.is_new || !!r.rewritten;
  // A departure is reported once, on the sweep that confirms it, not every
  // morning afterwards forever.
  return !!r.just_stopped;
});

// A filtering node that can return zero items ends the branch, and the quiet
// lane below would then never fire - so "nothing changed this morning" would be
// indistinguishable from "the workflow broke". One marker item carries the
// silence forward on purpose.
if (!worth.length) {
  return [{ json: {
    advertiser: '',
    watch_key: '',
    status: 'nothing',
    headline: '',
    ad_copy: '',
    query: '',
    country: '',
    quiet_count: rows.filter(function (r) { return r.advertiser; }).length,
  } }];
}
return worth.map(function (r) { return { json: r }; });

parameters.text:
=Read one Google Ads creative and say what the advertiser is doing with it.

The brand being watched: {{ $('Settings').first().json.brand_name }}
The advertiser: {{ $json.advertiser }}
The search that triggered it: {{ $json.query }} ({{ $json.country }})

Headline: {{ $json.headline }}
Ad copy: {{ $json.ad_copy }}

intent - comparison when it positions itself against the watched brand, imitation when it presents itself as the brand or as the brand's own page, resale when it offers the brand's own product for sale, unrelated when the copy has nothing to do with the brand and it simply bought the keyword.
names_your_brand - true only if the watched brand's name is literally written in the headline or copy above.
evidence - quote the words from the headline or copy that decide it, verbatim. Never write words that are not above.
reads_as - one short sentence a marketer could paste into Slack.

parameters.jsonSchemaExample:
{
  "intent": "comparison",
  "names_your_brand": true,
  "evidence": "Switch to Lightfield",
  "reads_as": "An AI-native CRM bidding switchers, no brand name in the copy."
}

parameters.jsCode:
// The arithmetic overrules the model on the one field that routes the item.
// Whether your brand name is written in an ad is a string test, and a string
// test cannot hallucinate; three templates on this account have had an enum come
// back outside its own schema. The model's reading is kept as prose, which is
// what it is actually good for.
const cfg = $('Settings').first().json;
const brand = String(cfg.brand_name || '').trim().toLowerCase();
const INTENTS = { comparison: 1, imitation: 1, resale: 1, unrelated: 1 };
const source = $('Only The Ones Worth Reading').all();

return $input.all().map(function (item, idx) {
  // The Information Extractor nests its result under `output`. Reading the
  // fields off $json directly gives undefined on every item, which produces an
  // empty report on a run where every node is green.
  const j = (item.json && item.json.output) || item.json || {};
  const src = source[idx];
  const r = src ? src.json : {};

  if (!r.advertiser) {
    return { json: { lane: 'quiet', quiet_count: Number(r.quiet_count) || 0 } };
  }

  let intent = String(j.intent || '').toLowerCase().trim();
  if (!INTENTS[intent]) intent = 'unrelated';

  const copy = (String(r.headline || '') + ' ' + String(r.ad_copy || '')).toLowerCase();
  const namesYou = !!brand && copy.indexOf(brand) >= 0;

  const evidence = String(j.evidence || '').trim();
  // A quote that is not in the creative is not evidence of anything.
  const quoted = !!evidence && copy.indexOf(evidence.toLowerCase().slice(0, 40)) >= 0;

  return { json: Object.assign({}, r, {
    intent: intent,
    names_your_brand: namesYou,
    model_said_names_you: !!j.names_your_brand,
    evidence: quoted ? evidence : '',
    reads_as: String(j.reads_as || '').trim(),
    lane: (r.status === 'live' && namesYou) ? 'escalate' : 'digest',
  }) };
});

// One message, however many advertisers. executeOnce on the Slack node would
// drop all but the first item; building the whole thing here keeps every finding
// and posts once.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r.advertiser; });

const lines = ['*Your brand name is in someone else\'s ad copy*'];
rows.forEach(function (r) {
  lines.push('');
  lines.push('*' + r.advertiser + '* - ' + r.intent + ' - on `' + r.query + '` (' + where(r) + ', ' + r.slot + ' slot ' + r.rank + ')');
  lines.push('> ' + r.headline);
  if (r.ad_copy) lines.push('> ' + r.ad_copy);
  if (r.evidence) lines.push('Names you: "' + r.evidence + '"');
  if (r.reads_as) lines.push('_' + r.reads_as + '_');
  lines.push('First seen ' + r.first_seen + ', ' + r.sweeps_seen + ' sweep(s)');
});
lines.push('');
lines.push('_Bidding on a brand keyword is usually allowed; using the name in the copy is the part that often is not. Read the ad yourself before you file anything._');

return [{ json: { message: lines.join('\n'), count: rows.length } }];

// New rivals and confirmed departures in one message, because they are the same
// question asked in two directions: who is spending against your name this
// fortnight.
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r.advertiser; });
// A market reads as its city. `Dallas,Texas,United States` is what Google needs
// and not what a person wants in a Slack line.
function where(r) { return String(r.location || r.country || '').split(',')[0]; }
// Three different things, and calling them all "new" is a lie the reader will
// act on. An advertiser who has bid for a fortnight and swapped their headline
// is not an arrival, and a headline change is often the more useful signal -
// it means the campaign was touched by a human this week.
const arrived = rows.filter(function (r) { return r.status === 'live' && r.is_new; });
const rewritten = rows.filter(function (r) { return r.status === 'live' && !r.is_new; });
const gone = rows.filter(function (r) { return r.status === 'stopped'; });

function entry(r) {
  const lines = ['- *' + r.advertiser + '* on `' + r.query + '` (' + where(r) + ', slot ' + r.rank + ') - ' + r.intent];
  lines.push('  > ' + r.headline);
  if (r.reads_as) lines.push('  _' + r.reads_as + '_');
  return lines;
}

const lines = [];
if (arrived.length) {
  lines.push('*New on your brand terms*');
  arrived.forEach(function (r) { entry(r).forEach(function (l) { lines.push(l); }); });
}
if (rewritten.length) {
  if (lines.length) lines.push('');
  lines.push('*Rewrote their ad*');
  rewritten.forEach(function (r) {
    entry(r).forEach(function (l) { lines.push(l); });
    if (r.prior_headline) lines.push('  was: ' + r.prior_headline);
    lines.push('  bidding ' + r.sweeps_seen + ' sweeps, since ' + r.first_seen);
  });
}
if (gone.length) {
  if (lines.length) lines.push('');
  lines.push('*Stopped bidding*');
  gone.forEach(function (r) {
    lines.push('- ' + r.advertiser + ' on `' + r.query + '` (' + where(r) + ') - absent ' + r.misses + ' sweeps running, after ' + r.sweeps_seen + ' with an ad');
  });
}
if (!lines.length) lines.push('Nothing new on your brand terms.');

return [{ json: { message: lines.join('\n'), count: rows.length } }];
